<?php declare(strict_types=1); ?>
<?php if($errors): ?><div class="alert"><?= kd_e(implode(' ',$errors)) ?></div><?php endif; ?>
<p class="module-intro">Hesap planı ve çift taraflı muhasebe fişlerini yönetin. Her fişte borç ve alacak toplamı otomatik doğrulanır.</p>
<div class="marketplace-grid">
<section class="panel customer-form-panel"><h3>Hesap planına hesap ekle</h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="account"><div class="customer-fields"><label>Hesap kodu *<input name="code" maxlength="30" required placeholder="100.01"></label><label>Hesap adı *<input name="name" maxlength="190" required></label><label>Hesap türü<select name="account_type"><option value="asset">Varlık</option><option value="liability">Yükümlülük</option><option value="equity">Özkaynak</option><option value="income">Gelir</option><option value="expense">Gider</option></select></label><label>Üst hesap<select name="parent_id"><option value="0">Ana hesap</option><?php foreach($accounts as $a): ?><option value="<?= (int)$a['id'] ?>"><?= kd_e($a['code'].' · '.$a['name']) ?></option><?php endforeach; ?></select></label></div><button class="btn primary">Hesabı ekle</button></form></section>
<section class="panel customer-form-panel"><h3>Yeni muhasebe fişi</h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="journal"><label>Fiş tarihi<input type="date" name="journal_date" value="<?= date('Y-m-d') ?>" required></label><label>Açıklama<input name="description" maxlength="255" required></label><h4>Fiş satırları</h4><?php for($i=0;$i<4;$i++): ?><div class="quality-row"><select name="account_id[]"><option value="0">Hesap seçin</option><?php foreach($active as $a): ?><option value="<?= (int)$a['id'] ?>"><?= kd_e($a['code'].' · '.$a['name']) ?></option><?php endforeach; ?></select><input type="number" name="debit[]" min="0" step=".01" placeholder="Borç"><input type="number" name="credit[]" min="0" step=".01" placeholder="Alacak"></div><?php endfor; ?><button class="btn primary" <?= count($active)<2?'disabled':'' ?>>Dengeli fişi kaydet</button></form></section>
</div>
<section class="panel customer-list-panel"><div class="panel-head"><h3>Hesap planı</h3><span class="muted"><?= count($accounts) ?> hesap</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Kod</th><th>Hesap adı</th><th>Tür</th><th>Üst hesap</th><th>Durum</th></tr></thead><tbody><?php foreach($accounts as $a): ?><tr><td><?= kd_e($a['code']) ?></td><td><?= kd_e($a['name']) ?></td><td><?= ['asset'=>'Varlık','liability'=>'Yükümlülük','equity'=>'Özkaynak','income'=>'Gelir','expense'=>'Gider'][$a['account_type']]??kd_e($a['account_type']) ?></td><td><?= kd_e($a['parent_name']??'—') ?></td><td><?= $a['is_active']?'Aktif':'Pasif' ?></td></tr><?php endforeach; ?><?php if(!$accounts): ?><tr><td colspan="5">Henüz hesap planı oluşturulmadı.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel customer-list-panel"><h3>Son muhasebe fişleri</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Fiş no</th><th>Tarih</th><th>Açıklama</th><th>Satır</th><th>Borç</th><th>Alacak</th></tr></thead><tbody><?php foreach($journals as $j): ?><tr><td><?= kd_e($j['journal_no']) ?></td><td><?= kd_e($j['journal_date']) ?></td><td><?= kd_e($j['description']) ?></td><td><?= (int)$j['line_count'] ?></td><td><?= number_format((float)$j['total_debit'],2,',','.') ?></td><td><?= number_format((float)$j['total_credit'],2,',','.') ?></td></tr><?php endforeach; ?><?php if(!$journals): ?><tr><td colspan="6">Henüz muhasebe fişi yok.</td></tr><?php endif; ?></tbody></table></div></section>
